 static int cases,comparisons,captures,frames,waits,failures;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}static void put(Object o,String k,Object v){try{SourceSignedRecoveryPlan.set(o,k,v);}catch(Exception e){throw new AssertionError(e);}}static Object state(ClientSession pc){return SourceElementTransportPlan.state(pc);}
 static void parity(NativePlayerCommit.Binding binding,ClientSession pc,String why){Object owner=CombatAccess.field(state(pc),"sourcePlayerOwner"),life=NativeSourceControlledDisplay.rawLife(pc);boolean old=binding.matches(pc);check(old==NativeSourceControlledRoleFrame.current(binding,pc),"same stable original binding semantics "+why);check(CombatAccess.field(state(pc),"sourcePlayerOwner")==owner&&NativeSourceControlledDisplay.rawLife(pc)==life,"stable role comparison preserves canonical owner/life "+why);comparisons++;}
