  Object status=CombatAccess.field(pc,"timedStatus"),s=state(pc),owner=CombatAccess.field(s,"sourcePlayerOwner");CombatAccess.set(s,"sourcePlayerOwner",null);check(!NativeSourceControlledRoleFrame.current(b,pc)&&CombatAccess.field(s,"sourcePlayerOwner")==null,"readonly comparison never recreates missing original role owner");check(!b.matches(pc)&&CombatAccess.field(s,"sourcePlayerOwner")!=null,"exact old binding.matches reproduces unwanted late role creation");CombatAccess.set(s,"sourcePlayerOwner",owner);CombatAccess.set(status,"sourcePoisonLifecycle",null);check(!NativeSourceControlledRoleFrame.current(b,pc)&&CombatAccess.field(status,"sourcePoisonLifecycle")==null,"readonly comparison never recreates missing lifecycle state");check(!b.matches(pc)&&CombatAccess.field(status,"sourcePoisonLifecycle")!=null,"exact old binding.matches reproduces lifecycle container creation");CombatAccess.set(status,"sourcePoisonLifecycle",s);var malformed=new NativePlayerCommit.Binding(null,b.object(),b.source(),b.account(),b.selected(),b.phase(),b.room(),b.map(),b.instance());check(!NativeSourceControlledRoleFrame.current(malformed,pc)&&!malformed.matches(pc),"null-owner legacy tuple cannot acquire qualified role authority");
